sp_widget.client_script:
function($scope, $rootScope, spUtil, $timeout) {
  $scope.anoSelecionado = "";
  $scope.dadosVisiveis = null;
  $scope.isFading = false;

  function carregarDados(ano) {
    $scope.isFading = true;
    $timeout(function() {
      if (ano === '' || ano == null) {
        $scope.dadosVisiveis = null;
        $scope.isFading = false;
        return;
      }

      spUtil.get('despesas_porcentagem_ano_executivo', { filtro_ano: ano }).then(function(response) {
        if (response.data && response.data.dados && response.data.dados.length > 0) {
          $scope.dadosVisiveis = response.data.dados[0];
        } else {
          $scope.dadosVisiveis = null;
        }
        $scope.isFading = false;
      });
    }, 500);
  }

  $rootScope.$on('anoSelecionado', function(evt, ano) {
    $scope.anoSelecionado = ano;
    carregarDados(ano);
  });

  carregarDados(new Date().getFullYear());
}

sp_widget.css:
div, h2, {
	font-family: 'Roboto Flex', sans-serif;
}

.report-widget {
    border-radius: 12px;
    box-shadow: 0 2px 6px rgba(0, 0, 0, 0.08);
    background-color: #fff;
    margin-top: 24px;
    overflow: hidden;
    display: flex;
    flex-direction: column;
    font-family: 'Roboto Flex', sans-serif;
    /* Transição para o fade + movimento vertical */
    opacity: 1;
    visibility: visible;
    transform: translateY(0);
    transition: opacity 0.5s ease-in-out, transform 0.5s ease-in-out, visibility 0.5s ease-in-out;
  }

  .report-widget.panel.fade-out {
    opacity: 0;
    visibility: hidden;
    transform: translateY(20px);

/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  .report-widget {
    margin-top: 1rem;
  }
  .panel-title {
    font-size: 1.5rem;
  }
  .panel-body {
    padding: 8px; 
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
