sp_widget.script:
(function() {
  /*function formatarNumero(valor, divisor, sufixo) {
    //var resultado = (valor / divisor).toFixed(3); // fixa 3 casas
    // insere separador de milhar com expressão regular
		var resultado = (valor / divisor); // fixa 3 casas
    resultado = resultado.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    return resultado + ' ' + sufixo;
  }*/

	  function formatarNumero(valor) {
        if (typeof valor !== 'number') {
            valor = parseFloat(valor);
        }

        return valor.toFixed(2) // fixa duas casas decimais
                    .replace('.', ',') // troca ponto decimal por vírgula
                    .replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // insere separadores de milhar
    }


  var anoFiltrado = (typeof input !== 'undefined' && input.filtro_ano) ? input.filtro_ano : '';
  var gr = new GlideRecord('x_sded9_portal_t_0_u_despesa_pessoal');

  if (anoFiltrado) {
    gr.addQuery('u_ano', anoFiltrado);
  }

  gr.orderByDesc('u_ano');
  gr.query();

  var dados = [];
  while (gr.next()) {
    var despesaLiquida = parseFloat(gr.getValue('despesa_total_com_pessoal_executivo_anual')) || 0;

    var valorFormatado;
    if (despesaLiquida >= 1) {
      valorFormatado = formatarNumero(despesaLiquida);
    } else {
      valorFormatado = formatarNumero(despesaLiquida);
    }

    dados.push({
      ano: gr.getValue('u_ano'),
      despesaLiquida: despesaLiquida,
      receitaCorrente: parseFloat(gr.getValue('u_receita_corrente_liquida')) || 0,
      comprometimento: parseFloat(gr.getValue('comprometimento_executivo')) || 0,
      limiteAlerta: parseFloat(gr.getValue('u_limite_de_alerta')) || 0,
      limitePrudencial: parseFloat(gr.getValue('u_limite_prudencial')) || 0,
      limiteMaximo: parseFloat(gr.getValue('u_limite_maximo')) || 0,
      valorDespesaFormatado: valorFormatado
    });
  }

	//gs.addInfoMessage(JSON.stringify(dados))

  data.dados = dados;
})();
